// Filtra notas fiscais integradas e com chave valida.
// Continuamos acompanhando ate a entrada fiscal, independentemente do SUL.
const out = [];
const seen = new Set();
for (const pagina of $input.all()) {
  for (const item of (pagina.json.value || [])) {
    const f = item.fields || {};
    const chave = String(f.CHAVE_NFE ?? '').trim();
    if (!/^\d{44}$/.test(chave)) continue;
    if (String(f.STATUS_INTEGRACAO || '').trim().toUpperCase() !== 'INTEGRADO') continue;
    if (seen.has(chave)) throw new Error('Chave NF-e duplicada na lista: ' + chave);
    seen.add(chave);
    out.push({json: { item_id: String(item.id), chave_nfe: chave }});
  }
}
return out;

// Compara entrada fiscal SQL com dados atuais da lista.
// Somente PATCH para datas novas/diferentes; NAO altera recebimento fisico.
const normalizar = v => String(v ?? '').trim();
const sql = $input.all();
const lista = $('02 - Ler lista SharePoint').all();
const originais = $('03 - Separar NFs para entrada fiscal').all();

const porId = new Map();
for (const pagina of lista) {
  for (const item of pagina.json.value || []) {
    porId.set(normalizar(item.id), item.fields || {});
  }
}
const idPorChave = new Map();
for (const item of originais) {
  const {item_id, chave_nfe} = item.json;
  if (idPorChave.has(chave_nfe)) throw new Error('Duplicidade de CHAVE_NFE: ' + chave_nfe);
  idPorChave.set(chave_nfe, normalizar(item_id));
}
const compararData = valor => {
  const v = normalizar(valor);
  return v ? v.slice(0,10) : '';
};
const out = [];
for (const item of sql) {
  const d = item.json;
  const chave = normalizar(d.CHAVE_NFE);
  const id = idPorChave.get(chave);
  if (!id) throw new Error('Chave nao encontrada na lista: ' + chave);
  const atual = porId.get(id) || {};
  const data = compararData(d.DATA_ENTRADA_FISCAL);
  // Nao sobrescreve valores ja presentes quando SQL nao tem entrada.
  if (!/^\d{4}-\d{2}-\d{2}$/.test(data)) continue;
  if (data === compararData(atual.DATA_ENTRADA_FISCAL)) continue;
  // Filial e devolvida para auditoria, nao atualizada automaticamente.
  out.push({json:{
    item_id: id,
    chave_nfe: chave,
    filial_entrada: normalizar(d.FILIAL_ENTRADA),
    fields:{ DATA_ENTRADA_FISCAL: data }
  }});
}
return out;
